#include "../src/effect_presentation_slots.h"
#include <stdio.h>
#include <assert.h>
#include <string.h>
int main(void){uint8_t tables[16388];FILE *f=fopen("outputs/crazy-taxi-native/assets/driving.ctr","rb");assert(f&&fread(tables,1,sizeof(tables),f)==sizeof(tables));fclose(f);TaxiTrig trig;taxi_trig_decode(&trig,tables+4,tables+8196);int x,y,z,pitch,yaw,roll,phase;unsigned count;while(scanf("%d%d%d%d%d%d%d%u",&x,&y,&z,&pitch,&yaw,&roll,&phase,&count)==8){assert(count<=9);TaxiEffectRecord records[9];TaxiEffectSprite requests[9]={0};for(unsigned n=0;n<9;n++)for(unsigned b=0;b<72;b++){unsigned v;assert(scanf("%u",&v)==1);records[n].bytes[b]=(uint8_t)v;}for(unsigned n=0;n<count;n++){int v[10];for(unsigned b=0;b<10;b++)assert(scanf("%d",v+b)==1);requests[n]=(TaxiEffectSprite){.position={v[0],v[1],v[2]},.scale=(int16_t)v[3],.group=(uint8_t)v[4],.frame=(uint8_t)v[5],.palette=(uint8_t)v[6],.bucket=(uint8_t)v[7],.priority=(uint8_t)v[8],.flags=(uint8_t)v[9]};}TaxiEffectRecord before[9];memcpy(before,records,sizeof(records));TaxiEffectPresentationSlot slots[9];assert(taxi_effect_presentation_slots(records,(TaxiPoint){x,y,z},pitch,yaw,roll,&trig,phase,requests,count,slots)==(int)count);assert(!memcmp(before,records,sizeof(records)));for(unsigned n=0;n<9;n++)if(slots[n].visible){TaxiEffectSprite s=slots[n].sprite;printf("%u %d %d %d %d %u %u %u %u %u %u\n",n,s.position.x,s.position.y,s.position.z,s.scale,s.group,s.frame,s.palette,s.bucket,s.priority,s.flags);}puts("END");}return 0;}
